{
  "application": "ppt-generation",
  "case_id": "case-artificial-analysis",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 6,
    "audience": "AI engineering leads and product managers evaluating LLM providers",
    "tone": "data-forward, professional"
  },
  "brief": {
    "title": "AI Model Landscape April 2026: Intelligence, Speed, and Pricing Benchmarks",
    "one_liner": "Gemini 3.1 Pro and GPT-5.4 tie at 57 on the Intelligence Index while a 33x pricing gap separates the cheapest and most expensive frontier models.",
    "goal": "Equip decision-makers with a clear, data-driven comparison of top LLMs across intelligence, throughput, and cost so they can select the right model for their use case."
  },
  "slides": [
    {
      "id": "title",
      "title": "AI Model Landscape April 2026: Benchmarking Intelligence, Speed, and Cost Across 11 Frontier Models",
      "objective": "Introduce the analysis scope and establish Artificial Analysis as the data source."
    },
    {
      "id": "intelligence",
      "title": "Gemini 3.1 Pro Preview and GPT-5.4 Co-Lead the Intelligence Index at 57",
      "objective": "Present the full intelligence ranking with scores for all 11 models, highlighting the two-way tie and the 57-to-33 spread."
    },
    {
      "id": "speed",
      "title": "gpt-oss-120B Tops Output Speed at 218 Tokens/s -- More Than 4x Faster Than Claude Opus 4.6",
      "objective": "Show the output-speed leaderboard (10 models with speed data; Muse Spark excluded) and emphasize the inverse relationship between intelligence and throughput."
    },
    {
      "id": "pricing",
      "title": "From $0.30 to $10 per Million Tokens: A 33x Pricing Gap Across Models",
      "objective": "Compare per-token pricing across the 10 models with published pricing data (Muse Spark excluded) and surface the most cost-effective options for budget-sensitive deployments."
    },
    {
      "id": "tradeoffs",
      "title": "No Model Wins on All Three Axes: Navigating the Intelligence-Efficiency-Cost Frontier",
      "objective": "Use the intelligence-vs-output-tokens-consumed scatter plot and the proprietary vs. open-weight summary table to illustrate that every model requires trade-offs among intelligence, token efficiency, and cost, guiding the audience toward use-case-driven selection."
    },
    {
      "id": "takeaways",
      "title": "Open Weights Close the Gap: GLM-5.1 Reaches 51 Intelligence at $2.10/M Tokens",
      "objective": "Summarize key findings and actionable recommendations for model selection."
    }
  ]
}

